import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`cash-flow-optimizer`,heroTitle:`Optimize your cash flow in minutes`,heroSubtitle:`Perplexity Computer connects your accounts, builds cash flow reports, and optimizes your 10-year net income — automatically.`,inputUrlPrefill:`Generate a personal cash flow report and help me optimize my 10-year net income. Connect my financial accounts via Plaid so you can pull my income and expense data. Then ask me about my income sources, expected salary trajectory, major upcoming expenses or life changes, and any financial goals I’m working toward. Build me a cash flow model and show me where I can improve.`,heroOverlaySteps:[`Connecting your financial accounts and pulling transaction history`,`Categorizing income streams, expenses, and recurring obligations`,`Modeling 10-year projections across multiple optimization scenarios`,`Cash flow reports, savings targets, and optimization plan — ready to execute`],featureSectionTitle:`From accounts to optimized income`,featureCardTitles:[`Connects to your finance stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`QuickBooks, Google Sheets, Xero, Stripe, Google Drive — Computer plugs into your tools so cash flow analysis and reporting happen in one workflow.`,`Monthly cash flow reports. 10-year net income projections. Expense reduction targets. Savings allocation plans. Computer delivers financial intelligence you can use immediately.`],capabilitySectionTitle:`Your financial analyst, on autopilot`,capabilitySectionSubtitle:`Connect your accounts, step away, come back to a complete cash flow strategy.`,capabilityCards:[{title:`Cash Flow Analysis`,description:`Computer can pull your transaction data, categorize every line item, and map your complete cash flow — income, expenses, and net position month by month.`},{title:`Income Optimization`,description:`Computer can model scenarios across tax strategies, debt paydown schedules, and investment allocations to maximize your 10-year net income.`},{title:`Expense Tracking`,description:`Computer can identify recurring charges, flag unnecessary spending, and surface cost-cutting opportunities — prioritized by annual impact.`},{title:`Connect Your Tools`,description:`Computer can read from QuickBooks, Xero, Google Sheets, Stripe, and more — build workflows across your entire financial stack.`},{title:`Remember & Learn`,description:`Computer can remember your income sources, financial goals, and risk tolerance across sessions — so every projection builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch your cash flow weekly and alert you when spending spikes, income dips, or projections shift off track.`}]});export{t as default};
